// 查看系统页大小
#include <unistd.h>
#include <stdio.h>

int main() {
    long page_size = sysconf(_SC_PAGESIZE);
    printf("Page size: %ld bytes\n", page_size); // 通常 4096

    // 查看进程内存段信息
    // 通过 /proc/self/maps 查看
    FILE *fp = fopen("/proc/self/maps", "r");
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        printf("%s", line);
    }
    fclose(fp);
    return 0;
}

// 典型输出展示了不同段：
// 代码段(r-xp): 存放可执行代码
// 数据段(rw-p): 存放全局变量和静态变量
// 堆(rw-p): 动态分配的内存
// 栈(rw-p): 函数调用栈
// mmap区: 共享库和 mmap 映射

